module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;
reg valid_out_next;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_in) begin
            sum <= sum + data_in;
            data_out <= sum + data_in;
            valid_out <= 1'b1;
        end else begin
            valid_out <= 1'b0;
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
    end else begin
        if (valid_in) begin
            sum <= sum + {2'b00, data_in}; // extend 8-bit to 10-bit
            data_out <= sum + {2'b00, data_in};
            valid_out <= 1'b1;
        end else begin
            valid_out <= 1'b0;
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [3:0] count;        // Counter for number of valid inputs
reg [9:0] sum;          // Accumulator for sum of inputs

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        sum <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        if (valid_in) begin
            if (count < 10) begin
                sum <= sum + data_in;
                count <= count + 1;
            end
            if (count == 9) begin
                data_out <= sum + data_in; // Final sum after 10 inputs
                valid_out <= 1;
                count <= 0; // Reset counter for next accumulation
                sum <= 0;   // Reset sum for next cycle
            end else begin
                valid_out <= 0;
            end
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule

