module adder_8bit(
    input [7:0] a, b,
    input cin,
    output [7:0] sum,
    output cout
);

wire [7:0] g, p;
wire [7:0] c;

// Generate and Propagate signals
assign g = a & b;
assign p = a ^ b;

// Carry for bit 0
assign c[0] = cin;

// Generate carry for bits 1 to 7
assign c[1] = g[0] | (p[0] & c[0]);
assign c[2] = g[1] | (p[1] & c[1]);
assign c[3] = g[2] | (p[2] & c[2]);
assign c[4] = g[3] | (p[3] & c[3]);
assign c[5] = g[4] | (p[4] & c[4]);
assign c[6] = g[5] | (p[5] & c[5]);
assign c[7] = g[6] | (p[6] & c[6]);

// Compute sum bits
assign sum = p ^ c[0:7];

// Carry out
assign cout = g[7] | (p[7] & c[7]);

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire c1, c2, c3, c4, c5, c6, c7;

    // Bit 0
    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign c1 = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);

    // Bit 1
    assign sum[1] = a[1] ^ b[1] ^ c1;
    assign c2 = (a[1] & b[1]) | (a[1] & c1) | (b[1] & c1);

    // Bit 2
    assign sum[2] = a[2] ^ b[2] ^ c2;
    assign c3 = (a[2] & b[2]) | (a[2] & c2) | (b[2] & c2);

    // Bit 3
    assign sum[3] = a[3] ^ b[3] ^ c3;
    assign c4 = (a[3] & b[3]) | (a[3] & c3) | (b[3] & c3);

    // Bit 4
    assign sum[4] = a[4] ^ b[4] ^ c4;
    assign c5 = (a[4] & b[4]) | (a[4] & c4) | (b[4] & c4);

    // Bit 5
    assign sum[5] = a[5] ^ b[5] ^ c5;
    assign c6 = (a[5] & b[5]) | (a[5] & c5) | (b[5] & c5);

    // Bit 6
    assign sum[6] = a[6] ^ b[6] ^ c6;
    assign c7 = (a[6] & b[6]) | (a[6] & c6) | (b[6] & c6);

    // Bit 7
    assign sum[7] = a[7] ^ b[7] ^ c7;
    assign cout = (a[7] & b[7]) | (a[7] & c7) | (b[7] & c7);

endmodule

module adder_8bit(
