    assign carry[0] = (a[0] & b[0]) | (a[0] ^ b[0]) & cin;

    // Bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry[0];
    assign c1 = (a[1] & b[1]) | ((a[1] ^ b[1]) & carry[0]);

    // Bit 2
    assign sum[2] = a[2] ^ b[2] ^ c1;
    assign c2 = (a[2] & b[2]) | ((a[2] ^ b[2]) & c1);

    // Bit 3
    assign sum[3] = a[3] ^ b[3] ^ c2;
    assign c3 = (a[3] & b[3]) | ((a[3] ^ b[3]) & c2);

    // Bit 4
    assign sum[4] = a[4] ^ b[4] ^ c3;
    assign c4 = (a[4] & b[4]) | ((a[4] ^ b[4]) & c3);

    // Bit 5
    assign sum[5] = a[5] ^ b[5] ^ c4;
    assign c5 = (a[5] & b[5]) | ((a[5] ^ b[5]) & c4);

    // Bit 6
    assign sum[6] = a[6] ^ b[6] ^ c5;
    assign c6 = (a[6] & b[6]) | ((a[6] ^ b[6]) & c5);

    // Bit 7
    assign sum[7] = a[7] ^ b[7] ^ c6;
    assign cout = (a[7] & b[7]) | ((a[7] ^ b[7]) & c6);

endmodule

module adder_8bit(
    input [7:0] a, b,
    input cin,
    output [7:0] sum,
    output cout
