module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire carry [15:0];

assign sum = a ^ b ^ {16{Cin}};
assign carry[0] = (a[0] & b[0]) | (a[0] & Cin) | (b[0] & Cin);
assign carry[15:1] = (a[15:1] & b[15:1]) | ((a[15:1] ^ b[15:1]) & {15{Cin}}) | (carry[14:0] << 1);

assign y = sum;
assign Co = carry[15];

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire carry [15:0];

assign sum[0] = a[0] ^ b[0] ^ Cin;
assign carry[0] = (a[0] & b[0]) | (Cin & (a[0] ^ b[0]));

genvar i;
generate
    for (i = 1; i < 16; i = i + 1) begin : full_adder_loop
        assign sum[i] = a[i] ^ b[i] ^ carry[i-1];
        assign carry[i] = (a[i] & b[i]) | (carry[i-1] & (a[i] ^ b[i]));
    end
endgenerate

assign y = sum;
assign Co = carry[15];

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire [15:0] carry;

assign sum = a ^ b ^ {16{Cin}};
assign carry[0] = a[0] & b[0] | (a[0] ^ b[0]) & Cin;

genvar i;
generate
    for (i = 1; i < 16; i = i + 1) begin : gen_add
        assign carry[i] = a[i] & b[i] | (a[i] ^ b[i]) & carry[i - 1];
        assign y[i] = a[i] ^ b[i] ^ carry[i - 1];
    end
endgenerate

assign y[0] = a[0] ^ b[0] ^ Cin;
assign Co = carry[15];

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] carry;

assign {carry[0], y[0]} = a[0] + b[0] + Cin;
assign {carry[1], y[1]} = a[1] + b[1] + carry[0];
assign {carry[2], y[2]} = a[2] + b[2] + carry[1];
assign {carry[3], y[3]} = a[3] + b[3] + carry[2];
assign {carry[4], y[4]} = a[4] + b[4] + carry[3];
assign {carry[5], y[5]} = a[5] + b[5] + carry[4];
assign {carry[6], y[6]} = a[6] + b[6] + carry[5];
assign {carry[7], y[7]} = a[7] + b[7] + carry[6];
assign {carry[8], y[8]} = a[8] + b[8] + carry[7];
assign {carry[9], y[9]} = a[9] + b[9] + carry[8];
assign {carry[10], y[10]} = a[10] + b[10] + carry[9];
assign {carry[11], y[11]} = a[11] + b[11] + carry[10];
assign {carry[12], y[12]} = a[12] + b[12] + carry[11];
assign {carry[13], y[13]} = a[13] + b[13] + carry[12];
assign {carry[14], y[14]} = a[14] + b[14] + carry[13];
assign {carry[15], y[15]} = a[15] + b[15] + carry[14];

assign Co = carry[15];

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire [14:0] carry;

// Generate full adder chain
assign {carry[14], sum[0]} = a[0] + b[0] + Cin;
generate
    genvar i;
    for (i = 1; i < 16; i = i + 1) begin : adder_loop
        assign {carry[i], sum[i]} = a[i] + b[i] + carry[i - 1];
    end
endgenerate

assign y = sum;
assign Co = carry[15 - 1]; // Carry out from the most significant bit

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire [14:0] carry;

// Generate full adders for bits 0 to 14
// Bit 0
assign sum[0] = a[0] ^ b[0] ^ Cin;
assign carry[0] = (a[0] & b[0]) | (a[0] & Cin) | (b[0] & Cin);

// Bits 1 to 14
genvar i;
generate
    for (i = 1; i < 15; i = i + 1) begin : full_adder_loop
        assign sum[i] = a[i] ^ b[i] ^ carry[i - 1];
        assign carry[i] = (a[i] & b[i]) | (a[i] & carry[i - 1]) | (b[i] & carry[i - 1]);
    end
endgenerate

// Bit 15
assign y = sum;
assign Co = (a[15] & b[15]) | (a[15] & carry[14]) | (b[15] & carry[14]);

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

wire [15:0] sum;
wire [15:0] carry;

// Stage 0: Least significant bit
assign sum[0] = a[0] ^ b[0] ^ Cin;
wire carry0_intermediate1 = a[0] & b[0];
wire carry0_intermediate2 = a[0] ^ b[0];
wire carry0 = carry0_intermediate1 | (carry0_intermediate2 & Cin);

