assign sum[1] = a[1] ^ b[1] ^ carry0;
wire carry1_intermediate1 = a[1] & b[1];
wire carry1_intermediate2 = a[1] ^ b[1];
wire carry1 = carry1_intermediate1 | (carry1_intermediate2 & carry0);

// Stage 2
assign sum[2] = a[2] ^ b[2] ^ carry1;
wire carry2_intermediate1 = a[2] & b[2];
wire carry2_intermediate2 = a[2] ^ b[2];
wire carry2 = carry2_intermediate1 | (carry2_intermediate2 & carry1);

// Stage 3
assign sum[3] = a[3] ^ b[3] ^ carry2;
wire carry3_intermediate1 = a[3] & b[3];
wire carry3_intermediate2 = a[3] ^ b[3];
wire carry3 = carry3_intermediate1 | (carry3_intermediate2 & carry2);

// Stage 4
assign sum[4] = a[4] ^ b[4] ^ carry3;
wire carry4_intermediate1 = a[4] & b[4];
wire carry4_intermediate2 = a[4] ^ b[4];
wire carry4 = carry4_intermediate1 | (carry4_intermediate2 & carry3);

// Stage 5
assign sum[5] = a[5] ^ b[5] ^ carry4;
wire carry5_intermediate1 = a[5] & b[5];
wire carry5_intermediate2 = a[5] ^ b[5];
wire carry5 = carry5_intermediate1 | (carry5_intermediate2 & carry4);

// Stage 6
assign sum[6] = a[6] ^ b[6] ^ carry5;
wire carry6_intermediate1 = a[6] & b[6];
wire carry6_intermediate2 = a[6] ^ b[6];
wire carry6 = carry6_intermediate1 | (carry6_intermediate2 & carry5);

// Stage 7
assign sum[7] = a[7] ^ b[7] ^ carry6;
wire carry7_intermediate1 = a[7] & b[7];
wire carry7_intermediate2 = a[7] ^ b[7];
wire carry7 = carry7_intermediate1 | (carry7_intermediate2 & carry6);

// Stage 8
assign sum[8] = a[8] ^ b[8] ^ carry7;
wire carry8_intermediate1 = a[8] & b[8];
wire carry8_intermediate2 = a[8] ^ b[8];
wire carry8 = carry8_intermediate1 | (carry8_intermediate2 & carry7);

// Stage 9
assign sum[9] = a[9] ^ b[9] ^ carry8;
wire carry9_intermediate1 = a[9] & b[9];
wire carry9_intermediate2 = a[9] ^ b[9];
wire carry9 = carry9_intermediate1 | (carry9_intermediate2 & carry8);

// Stage 10
assign sum[10] = a[10] ^ b[10] ^ carry9;
wire carry10_intermediate1 = a[10] & b[10];
wire carry10_intermediate2 = a[10] ^ b[10];
wire carry10 = carry10_intermediate1 | (carry10_intermediate2 & carry9);

// Stage 11
assign sum[11] = a[11] ^ b[11] ^ carry10;
wire carry11_intermediate1 = a[11] & b[11];
wire carry11_intermediate2 = a[11] ^ b[11];
wire carry11 = carry11_intermediate1 | (carry11_intermediate2 & carry10);

// Stage 12
assign sum[12] = a[12] ^ b[12] ^ carry11;
wire carry12_intermediate1 = a[12] & b[12];
wire carry12_intermediate2 = a[12] ^ b[12];
wire carry12 = carry12_intermediate1 | (carry12_intermediate2 & carry11);

// Stage 13
assign sum[13] = a[13] ^ b[13] ^ carry12;
wire carry13_intermediate1 = a[13] & b[13];
wire carry13_intermediate2 = a[13] ^ b[13];
wire carry13 = carry13_intermediate1 | (carry13_intermediate2 & carry12);

// Stage 14
assign sum[14] = a[14] ^ b[14] ^ carry13;
wire carry14_intermediate1 = a[14] & b[14];
wire carry14_intermediate2 = a[14] ^ b[14];
wire carry14 = carry14_intermediate1 | (carry14_intermediate2 & carry13);

// Stage 15
assign sum[15] = a[15] ^ b[15] ^ carry14;
wire carry15_intermediate1 = a[15] & b[15];
wire carry15_intermediate2 = a[15] ^ b[15];
wire carry15 = carry15_intermediate1 | (carry15_intermediate2 & carry14);

// Final carry out
assign Co = carry15;
assign y = sum;

endmodule

module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

