wire carry [15:0];

assign sum = a ^ b ^ {16{Cin}};
assign carry[0] = (a[0] & b[0]) | (a[0] & Cin) | (b[0] & Cin);
assign carry[15] = (a[15] & b[15]) | (a[15] & carry[14]) | (b[15] & carry[14]);

generate
    genvar i;
    for (i = 1; i < 16; i = i + 1) begin : carry_gen
        assign carry[i] = (a[i] & b[i]) | (a[i] & carry[i-1]) | (b[i] & carry[i-1]);
    end
endgenerate

