module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [STG_WIDTH-1:0] count;
reg [DATA_WIDTH:0] sum;
reg en_pipe;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        sum <= 0;
        o_en <= 0;
        en_pipe <= 0;
    end else begin
        if (i_en) begin
            sum <= {1'b0, adda} + {1'b0, addb};
            count <= 1;
            en_pipe <= 1;
            o_en <= 0;
        end else if (en_pipe) begin
            if (count < STG_WIDTH) begin
                count <= count + 1;
            end else begin
                o_en <= 1;
                en_pipe <= 0;
            end
        end
    end
end

assign result = sum;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH];

integer i;

// Pipeline registers for inputs
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i <= STG_WIDTH - 1; i = i + 1) begin
            adda_reg[i] <= {DATA_WIDTH{1'b0}};
            addb_reg[i] <= {DATA_WIDTH{1'b0}};
        end
        o_en <= 1'b0;
    end else if (i_en) begin
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        o_en <= 1'b0;
    end
end

// Shift registers for pipeline
generate
    genvar stage;
    for (stage = 1; stage < STG_WIDTH; stage = stage + 1) begin : shift_stages
        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                adda_reg[stage] <= {DATA_WIDTH{1'b0}};
                addb_reg[stage] <= {DATA_WIDTH{1'b0}};
            end else if (i_en) begin
                adda_reg[stage] <= adda_reg[stage - 1];
                addb_reg[stage] <= addb_reg[stage - 1];
            end
        end
    end
endgenerate

// Adders at each stage
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg[0] <= {(DATA_WIDTH+1){1'b0}};
        o_en <= 1'b0;
    end else if (i_en) begin
        sum_reg[0] <= {1'b0, adda_reg[0]} + {1'b0, addb_reg[0]};
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            sum_reg[i] <= sum_reg[i - 1] + {1'b0, adda_reg[i]} + {1'b0, addb_reg[i]};
        end
        if (i_en && (stage == STG_WIDTH - 1))
            o_en <= 1'b1;
    end
end

assign result = sum_reg[STG_WIDTH - 1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH];

reg [4:0] stage_counter; // enough bits to count up to STG_WIDTH

// Initialize registers
integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        o_en <= 0;
        stage_counter <= 0;
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
        end
    end else begin
        if (i_en) begin
            // Load input into first stage
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            sum_reg[0] <= {1'b0, adda} + {1'b0, addb};
            stage_counter <= 1;
            o_en <= 0;
        end else if (stage_counter != 0) begin
            // Shift data through pipeline
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1];
            end
            if (stage_counter < STG_WIDTH) begin
                stage_counter <= stage_counter + 1;
            end
            if (stage_counter == STG_WIDTH) begin
                // Output result at last stage
                result <= sum_reg[STG_WIDTH - 1];
                o_en <= 1;
                stage_counter <= 0; // reset counter after output
            end
        end else begin
            o_en <= 0; // default disable output
        end
    end
end

assign result = sum_reg[STG_WIDTH - 1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

// Internal registers for pipeline stages
reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];

integer i;

// Input registration
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
            sum_reg[i] <= 0;
        end
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            sum_reg[0] <= adda + addb;
            o_en <= 0;
        end else begin
            // propagate through pipeline
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1];
            end
            // set output enable when last stage sums are ready
            if (i_en) begin
                o_en <= 1;
            end
        end
    end
end

// Output assignment
assign result = sum_reg[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH];

reg [4:0] stage_counter; // enough bits to count up to STG_WIDTH

// Pipeline registers for input
integer i;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
        end
        stage_counter <= 0;
        o_en <= 0;
    end else if (i_en) begin
        // Shift in new inputs at stage 0
        adda_reg[0] <= adda;
        addb_reg[0] <= addb;
        stage_counter <= 1;
        o_en <= 0;
    end else if (stage_counter != 0 && stage_counter < STG_WIDTH) begin
        // Shift registers
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            adda_reg[i] <= adda_reg[i-1];
            addb_reg[i] <= addb_reg[i-1];
        end
        stage_counter <= stage_counter + 1;
        if (stage_counter + 1 == STG_WIDTH)
            o_en <= 1;
        else
            o_en <= 0;
    end else begin
        o_en <= 0;
    end
end

// Generate sum at each stage
reg [DATA_WIDTH:0] sum_next [0:STG_WIDTH];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i <= STG_WIDTH; i = i + 1) begin
            sum_reg[i] <= 0;
        end
    end else if (stage_counter > 0 && stage_counter <= STG_WIDTH) begin
        // Compute sum for current stage
        sum_next[0] <= {1'b0, adda_reg[0]} + {1'b0, addb_reg[0]};
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            sum_next[i] <= sum_reg[i-1];
        end
        // Shift sum_reg
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            sum_reg[i] <= sum_next[i];
        end
    end
end

// Final result assignment
assign result = (stage_counter == STG_WIDTH) ? sum_reg[STG_WIDTH-1] : 0;

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH];

reg [4:0] stage_cnt; // enough bits to count up to STG_WIDTH

// Pipeline control
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage_cnt <= 0;
        o_en <= 0;
    end else begin
        if (i_en && stage_cnt == 0) begin
            stage_cnt <= 1;
        end else if (stage_cnt != 0 && stage_cnt < STG_WIDTH) begin
            stage_cnt <= stage_cnt + 1;
        end else if (stage_cnt == STG_WIDTH) begin
            stage_cnt <= 0; // reset after last stage
        end

        // Output enable logic
        if (stage_cnt == STG_WIDTH)
            o_en <= 1;
        else
            o_en <= 0;
    end
end

// Input registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        integer i;
        for (i=0; i<STG_WIDTH; i=i+1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
            sum_reg[i] <= 0;
        end
    end else begin
        if (i_en && stage_cnt == 0) begin
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
        end
        // Shift registers for subsequent stages
        integer j;
        for (j=1; j<STG_WIDTH; j=j+1) begin
            if (stage_cnt == j) begin
                adda_reg[j] <= adda_reg[j-1];
                addb_reg[j] <= addb_reg[j-1];
            end
        end
    end
end

// Adders at each stage
reg [DATA_WIDTH:0] sum [0:STG_WIDTH-1];

integer k;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (k=0; k<STG_WIDTH; k=k+1) begin
            sum[k] <= 0;
        end
    end else begin
        for (k=0; k<STG_WIDTH; k=k+1) begin
            if (stage_cnt == k+1) begin
                sum[k] <= {1'b0, adda_reg[k]} + {1'b0, addb_reg[k]};
                sum_reg[k+1] <= sum[k];
            end
        end
    end
end

// Final result assignment
assign result = (stage_cnt == STG_WIDTH) ? sum_reg[STG_WIDTH] : {DATA_WIDTH+1{1'b0}};

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH:0] stage [0:STG_WIDTH-1];
reg [STG_WIDTH-1:0] valid_pipe;
integer i;

// Initialize output enable
initial begin
    o_en = 0;
end

// Pipeline logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            stage[i] <= 0;
        end
        valid_pipe <= 0;
        o_en <= 0;
    end else if (i_en) begin
        // Input stage
        stage[0] <= adda + addb;
        valid_pipe[0] <= 1;
        // Shift through pipeline
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            stage[i] <= stage[i-1];
            valid_pipe[i] <= valid_pipe[i-1];
        end
        // Output valid signal
        o_en <= valid_pipe[STG_WIDTH-1];
    end else begin
        // Hold previous states if not enabled
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            stage[i] <= stage[i];
            valid_pipe[i] <= valid_pipe[i];
        end
        o_en <= valid_pipe[STG_WIDTH-1];
    end
end

assign result = stage[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];
reg [STG_WIDTH-1:0] valid_reg;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            sum_reg[i] <= 0;
        end
        valid_reg <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            sum_reg[0] <= {1'b0, adda} + {1'b0, addb};
            valid_reg[0] <= 1'b1;
        end else begin
            sum_reg[0] <= sum_reg[0]; // hold value
            valid_reg[0] <= valid_reg[0];
        end
        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            if (valid_reg[i-1]) begin
                sum_reg[i] <= sum_reg[i-1];
                valid_reg[i] <= 1'b1;
            end else begin
                sum_reg[i] <= sum_reg[i]; // hold
                valid_reg[i] <= valid_reg[i]; // hold
            end
        end
        o_en <= valid_reg[STG_WIDTH-1];
    end
end

assign result = sum_reg[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];

reg [4:0] stage_cnt; // enough bits to count up to STG_WIDTH

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        o_en <= 1'b0;
        stage_cnt <= 0;
        // Initialize pipeline registers
        for (i = 0; i <= STG_WIDTH-1; i = i + 1) begin
            adda_reg[i] <= 0;
            addb_reg[i] <= 0;
            sum_reg[i] <= 0;
        end
    end else begin
        if (i_en) begin
            // Load first stage
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            sum_reg[0] <= adda + addb; // initial sum
            stage_cnt <= 1;
            o_en <= 1'b0; // not yet valid output
        end else if (stage_cnt > 0) begin
            // Shift pipeline
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1];
            end
            stage_cnt <= stage_cnt + 1;
            if (stage_cnt == STG_WIDTH) begin
                // Final stage: output result
                result <= sum_reg[STG_WIDTH-1];
                o_en <= 1'b1;
            end
        end else begin
            // Hold o_en low when not processing
            o_en <= 1'b0;
        end
    end
end

assign result = (stage_cnt == STG_WIDTH) ? sum_reg[STG_WIDTH-1] : {DATA_WIDTH+1{1'b0}};

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];

reg [4:0] stage_counter;

wire [DATA_WIDTH:0] sum_next;

assign sum_next = adda_reg[0] + addb_reg[0];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage_counter <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg[0] <= adda;
            addb_reg[0] <= addb;
            sum_reg[0] <= sum_next;
            stage_counter <= 1;
            o_en <= 0;
        end else if (stage_counter != 0) begin
            integer i;
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1];
            end
            stage_counter <= stage_counter + 1;
            if (stage_counter == STG_WIDTH) begin
                o_en <= 1;
            end
        end
        if (o_en) begin
            stage_counter <= 0;
        end
    end
end

assign result = sum_reg[STG_WIDTH-1];

endmodule

module asyn_fifo#(
	parameter WIDTH = 8,
	parameter DEPTH = 16
)(
	input wclk, 
	input rclk,   
	input wrstn,
	input rrstn,
	input winc,
	input rinc,
	input [WIDTH-1:0] wdata,
	output wire wfull,
	output wire rempty,
	output wire [WIDTH-1:0] rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

reg [ADDR_WIDTH-1:0] wptr, wptr_gray, rptr, rptr_gray;
reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
reg [ADDR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

reg [WIDTH-1:0] mem [0:DEPTH-1];

wire [ADDR_WIDTH-1:0] wptr_next, rptr_next;
wire [ADDR_WIDTH-1:0] wptr_gray_next, rptr_gray_next;

wire wfull_int, rempty_int;

// Write pointer logic
assign wptr_next = wptr + (winc & ~wfull);
assign wptr_gray_next = (wptr_next >> 1) ^ wptr_next;

// Read pointer logic
assign rptr_next = rptr + (rinc & ~rempty);
assign rptr_gray_next = (rptr_next >> 1) ^ rptr_next;

// Synchronize wptr_gray into read clock domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_gray_sync1 <= 0;
		wptr_gray_sync2 <= 0;
	end else begin
		wptr_gray_sync1 <= wptr_gray_next;
		wptr_gray_sync2 <= wptr_gray_sync1;
	end
end

// Synchronize rptr_gray into write clock domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_gray_sync1 <= 0;
		rptr_gray_sync2 <= 0;
	end else begin
		rptr_gray_sync1 <= rptr_gray_next;
		rptr_gray_sync2 <= rptr_gray_sync1;
	end
end

// Update pointers
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		wptr <= 0;
		wptr_gray <= 0;
	end else begin
		wptr <= wptr_next;
		wptr_gray <= wptr_gray_next;
	end
end

always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		rptr <= 0;
		rptr_gray <= 0;
	end else begin
		rptr <= rptr_next;
		rptr_gray <= rptr_gray_next;
	end
end

// Calculate full and empty flags
assign wfull_int = (wptr_gray_next == (rptr_gray_sync2 ^ {ADDR_WIDTH{1'b1}}));
assign rempty_int = (rptr_gray_next == wptr_gray_sync2);

assign wfull = wfull_int;
assign rempty = rempty_int;

// Write data
always @(posedge wclk) begin
	if (winc && !wfull) begin
		mem[wptr[ADDR_WIDTH-1:0]] <= wdata;
	end
end

// Read data
assign rdata = mem[rptr[ADDR_WIDTH-1:0]];

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input 					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

reg [ADDR_WIDTH-1:0] wptr = 0;
reg [ADDR_WIDTH-1:0] rptr = 0;

reg [ADDR_WIDTH:0] wbin_count = 0;
reg [ADDR_WIDTH:0] rbin_count = 0;

reg [WIDTH-1:0] mem [0:DEPTH-1];

wire [ADDR_WIDTH-1:0] waddr = wptr;
wire [ADDR_WIDTH-1:0] raddr = rptr;

wire [ADDR_WIDTH:0] wbin_next;
wire [ADDR_WIDTH:0] rbin_next;

wire wfull_next;
wire rempty_next;

// Write pointer and binary count update
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		wptr <= 0;
		wbin_count <= 0;
	end else if (winc && !wfull) begin
		wptr <= wptr + 1;
		wbin_count <= wbin_count + 1;
	end
end

// Read pointer and binary count update
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		rptr <= 0;
		rbin_count <= 0;
	end else if (rinc && !rempty) begin
		rptr <= rptr + 1;
		rbin_count <= rbin_count + 1;
	end
end

// Generate full and empty flags
assign wfull_next = (wbin_count - rbin_count) == DEPTH;
assign rempty_next = (wbin_count == rbin_count);

assign wfull = wfull_next;
assign rempty = rempty_next;

// Read data
assign rdata = mem[raddr];

// Write data
always @(posedge wclk) begin
	if (winc && !wfull) begin
		mem[waddr] <= wdata;
	end
end

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input 					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Write pointer and read pointer registers
reg [ADDR_WIDTH:0] wptr_bin, rptr_bin;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;
reg [ADDR_WIDTH:0] wptr_gray_sync1, wptr_gray_sync2;
reg [ADDR_WIDTH:0] rptr_gray_sync1, rptr_gray_sync2;

// Write FIFO memory
reg [WIDTH-1:0] mem [0:DEPTH-1];

// Synchronizer registers for pointers
reg [ADDR_WIDTH:0] wptr_gray_sync_rclk1, wptr_gray_sync_rclk2;
reg [ADDR_WIDTH:0] rptr_gray_sync_wclk1, rptr_gray_sync_wclk2;

// Wfull and Rempty signals
reg wfull_reg, rempty_reg;

// Assign outputs
assign wfull = wfull_reg;
assign rempty = rempty_reg;

// Read data output
reg [WIDTH-1:0] rdata_reg;
assign rdata = rdata_reg;

// Synchronize write pointer Gray code into read clock domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_gray_sync1 <= {ADDR_WIDTH+1{1'b0}};
		wptr_gray_sync2 <= {ADDR_WIDTH+1{1'b0}};
	end else begin
		wptr_gray_sync1 <= wptr_gray;
		wptr_gray_sync2 <= wptr_gray_sync1;
	end
end

// Synchronize read pointer Gray code into write clock domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_gray_sync1 <= {ADDR_WIDTH+1{1'b0}};
		rptr_gray_sync2 <= {ADDR_WIDTH+1{1'b0}};
	end else begin
		rptr_gray_sync1 <= rptr_gray;
		rptr_gray_sync2 <= rptr_gray_sync1;
	end
end

// Convert binary to Gray code
function [ADDR_WIDTH:0] bin2gray;
	input [ADDR_WIDTH:0] bin;
	begin
		bin2gray = (bin >> 1) ^ bin;
	end
endfunction

// Convert Gray code to binary
function [ADDR_WIDTH:0] gray2bin;
	input [ADDR_WIDTH:0] gray;
	reg [ADDR_WIDTH:0] bin;
	integer i;
	begin
		bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
		for (i = ADDR_WIDTH-1; i >= 0; i = i -1) begin
			bin[i] = bin[i+1] ^ gray[i];
		end
		gray2bin = bin;
	end
endfunction

// Write pointer logic
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		wptr_bin <= 0;
		wptr_gray <= 0;
	end else if (winc && !wfull_reg) begin
		wptr_bin <= wptr_bin + 1;
		wptr_gray <= bin2gray(wptr_bin + 1);
	end
end

// Read pointer logic
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		rptr_bin <= 0;
		rptr_gray <= 0;
	end else if (rinc && !rempty_reg) begin
		rptr_bin <= rptr_bin + 1;
		rptr_gray <= bin2gray(rptr_bin + 1);
	end
end

// Generate wfull signal
always @(*) begin
	wfull_reg = 0;
	if ((wptr_gray == {~rptr_gray_sync2[ADDR_WIDTH], rptr_gray_sync2[ADDR_WIDTH-1:0]})) begin
		wfull_reg = 1;
	end
end

// Generate rempty signal
reg rempty_next;
always @(*) begin
	if (wptr_gray == rptr_gray_sync2) begin
		rempty_next = 1;
	end else begin
		rempty_next = 0;
	end
end
always @(*) begin
	rempty_reg = rempty_next;
end

// Write data into memory
always @(posedge wclk) begin
	if (winc && !wfull_reg) begin
		mem[wptr_bin[ADDR_WIDTH-1:0]] <= wdata;
	end
end

// Read data from memory
always @(posedge rclk) begin
	if (rinc && !rempty_reg) begin
		rdata_reg <= mem[rptr_bin[ADDR_WIDTH-1:0]];
	end
end

endmodule

module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input 					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
