module multi_16bit(
    input clk,          
    input rst_n,        
    input start,        
    input [15:0] ain,   
    input [15:0] bin,   

    output reg [31:0] yout, 
    output reg done         
);

reg [15:0] multiplicand;
reg [15:0] multiplier;
reg [31:0] product;
reg [4:0] count; // 5 bits to count up to 16
reg busy;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        yout <= 0;
        product <= 0;
        multiplicand <= 0;
        multiplier <= 0;
        count <= 0;
        done <= 0;
        busy <= 0;
    end else begin
        if (start && !busy) begin
            // Initialize for new multiplication
            multiplicand <= ain;
            multiplier <= bin;
            product <= 0;
            count <= 0;
            done <= 0;
            busy <= 1;
        end else if (busy) begin
            if (multiplier[0]) begin
                product <= product + (multiplicand << count);
            end
            multiplier <= multiplier >> 1;
            count <= count + 1;
            if (count == 16) begin
                yout <= product;
                done <= 1;
                busy <= 0;
            end
        end else begin
            done <= 0; // Clear done flag after operation completes
        end
    end
end

endmodule

