   // For simplicity, we process bits from LSB to MSB with overlapping pairs
   // Generate booth code for each pair

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         product <= 0;
         count <= 0;
         rdy_reg <= 0;
         b_reg <= 0;
