   assign booth_code = {booth_multiplier[1], booth_multiplier[0], booth_multiplier[2]};

   // Sign extension of multiplicand for negative partial products
   wire [15:0] a_ext = { {8{a_reg[7]}}, a_reg };

   // Booth encoding to generate partial products
   always @(posedge clk or posedge reset) begin
