               3'b001, 3'b010: partial_products[count] <= a_ext;
               3'b011: partial_products[count] <= a_ext << 1;
               3'b100: partial_products[count] <= -(a_ext << 1);
               3'b101, 3'b110: partial_products[count] <= -a_ext;
               default: partial_products[count] <= 16'b0;
           endcase
           // Shift Booth multiplier for next group
           booth_multiplier <= booth_multiplier >> 2;
           count <= count + 1;
