           rdy_reg <= 0;
           count <= 4;
           multiplicand <= a;
           b_ext <= {b[7], b}; // extend with sign bit for Booth
           multiplier <= b;
           product <= 0;
           partial_sum <= 0;
       end else if (count > 0) begin
           // Booth multiplication process
           booth_code <= {multiplier[1:0], 1'b0}; // take 2 bits per step
           case (booth_code)
               3'b000, 3'b111: begin
