		a_reg[0] <= 0;
		b_reg[0] <= 0;
		a_reg[1] <= 0;
		b_reg[1] <= 0;
		product_reg[0] <= 0;
		product_reg[1] <= 0;
		mul_out <= 0;
	end else begin
		// Stage 1: Register inputs
		a_reg[0] <= mul_a;
		b_reg[0] <= mul_b;

		// Stage 2: Perform multiplication
		a_mult <= a_reg[0];
		b_mult <= b_reg[0];
		product_mult <= a_mult * b_mult;
		product_reg[0] <= product_mult;

		// Stage 3: Register the product
		a_reg[1] <= a_reg[0];
		b_reg[1] <= b_reg[0];
		product_reg[1] <= product_reg[0];

		// Final output assignment
		mul_out <= product_reg[1];
