module multi_pipe_4bit#(
    parameter size = 4
)(
    input                       clk        ,   
    input                       rst_n      ,
    input   [size-1:0]          mul_a      ,
    input   [size-1:0]          mul_b      ,
    output  reg [size*2-1:0]    mul_out    
);

parameter N = 2 * size;

reg [size-1:0] a_reg [0:1];
reg [size-1:0] b_reg [0:1];
reg [N-1:0] partial_products [0:1];

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_reg[0] <= 0;
        b_reg[0] <= 0;
        a_reg[1] <= 0;
        b_reg[1] <= 0;
        for (i = 0; i < 2; i = i + 1) begin
            partial_products[i] <= 0;
        end
        mul_out <= 0;
    end else begin
        // Stage 0: register inputs
        a_reg[0] <= mul_a;
        b_reg[0] <= mul_b;

        // Stage 1: compute partial products
        for (i = 0; i < size; i = i + 1) begin
            if (b_reg[0][i] == 1'b1) begin
                partial_products[0][(i*size) +: size] <= a_reg[0];
            end else begin
                partial_products[0][(i*size) +: size] <= 0;
            end
        end

        // Shift partial products to next stage
        a_reg[1] <= a_reg[0]; // Keep for possible further stages
        b_reg[1] <= b_reg[0];

        // Accumulate shifted partial products
        reg [N-1:0] sum;
        sum = 0;
        for (i = 0; i < size; i = i + 1) begin
            if (b_reg[0][i] == 1'b1) begin
                sum = sum + (a_reg[0] << i);
            end
        end
        // Assign the result at the last cycle
        mul_out <= sum;
    end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [size-1:0] a_reg [0:N-1];
reg [size-1:0] b_reg [0:N-1];
reg [size*2-1:0] partial_products [0:N-1];

integer i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		for (i = 0; i < N; i = i + 1) begin
			a_reg[i] <= 0;
			b_reg[i] <= 0;
			partial_products[i] <= 0;
		end
		mul_out <= 0;
	end else begin
		// Load inputs into registers
		a_reg[0] <= mul_a;
		b_reg[0] <= mul_b;
		// Generate partial products
		for (i = 0; i < size; i = i + 1) begin
			if (b_reg[0][i]) begin
				partial_products[i] <= a_reg[0] << i;
			end else begin
				partial_products[i] <= 0;
			end
		end
		// Shift partial products for next stage
		for (i = 1; i < size; i = i + 1) begin
			a_reg[i] <= a_reg[i-1];
			b_reg[i] <= b_reg[i-1] >> 1;
			if (b_reg[i][0]) begin
				partial_products[i] <= a_reg[i] << 0;
			end else begin
				partial_products[i] <= 0;
			end
		end
		// Sum partial products
		reg [size*2-1:0] sum;
		sum = 0;
		for (i = 0; i < size; i = i + 1) begin
			sum = sum + partial_products[i];
		end
		mul_out <= sum;
	end
end

endmodule

module multi_pipe_4bit#(
