	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [size-1:0] a_reg, b_reg;
reg [size-1:0] a_reg2, b_reg2;
reg [size-1:0] a_reg3, b_reg3;
reg [size-1:0] a_reg4, b_reg4;

reg [N-1:0] partial_sum1;
reg [N-1:0] partial_sum2;
reg [N-1:0] partial_sum3;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_reg <= 0;
        b_reg <= 0;
        a_reg2 <= 0;
        b_reg2 <= 0;
        a_reg3 <= 0;
        b_reg3 <= 0;
        a_reg4 <= 0;
        b_reg4 <= 0;
        mul_out <= 0;
        partial_sum1 <= 0;
        partial_sum2 <= 0;
        partial_sum3 <= 0;
    end else begin
        // Stage 1
        a_reg <= mul_a;
        b_reg <= mul_b;
        // Stage 2
        a_reg2 <= a_reg;
        b_reg2 <= b_reg;
        // Stage 3
        a_reg3 <= a_reg2;
        b_reg3 <= b_reg2;
        // Stage 4
        a_reg4 <= a_reg3;
        b_reg4 <= b_reg3;

        // Partial products
        // Stage 1 partial products
        reg [size-1:0] a1 = a_reg;
        reg [size-1:0] b1 = b_reg;
        reg [size-1:0] a2 = a_reg2;
        reg [size-1:0] b2 = b_reg2;
        reg [size-1:0] a3 = a_reg3;
        reg [size-1:0] b3 = b_reg3;
        reg [size-1:0] a4 = a_reg4;
        reg [size-1:0] b4 = b_reg4;

        // Compute partial products
        // Since no 'break', compute all partial products directly
        wire [2*size-1:0] p1 = a1 * b1;
        wire [2*size-1:0] p2 = a2 * b2;
        wire [2*size-1:0] p3 = a3 * b3;
        wire [2*size-1:0] p4 = a4 * b4;

        // Shift partial products according to their position
        // p1: no shift
        // p2: shift left by size bits
        // p3: shift left by 2*size bits
        // p4: shift left by 3*size bits

        // Sum all partials to get final output
        // Use temporary registers to hold sums
        reg [N-1:0] sum1, sum2, sum3;

        always @(posedge clk or negedge rst_n) begin
            if (!rst_n) begin
                sum1 <= 0;
                sum2 <= 0;
                sum3 <= 0;
                mul_out <= 0;
            end else begin
                sum1 <= p1 + (p2 << size);
                sum2 <= sum1 + (p3 << (2*size));
                sum3 <= sum2 + (p4 << (3*size));
                mul_out <= sum3;
            end
        end
    end
end

