module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [size-1:0] a_reg, b_reg;
reg [2*size-1:0] partial_products [0:size-1];

integer i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		a_reg <= mul_a;
		b_reg <= mul_b;

		// Generate partial products
		for (i = 0; i < size; i = i + 1) begin
			if (b_reg[i]) begin
				partial_products[i] <= (a_reg << i);
			end else begin
				partial_products[i] <= 0;
			end
		end

		// Sum partial products
		mul_out <= 0;
		for (i = 0; i < size; i = i + 1) begin
			mul_out <= mul_out + partial_products[i];
		end
	end
end

endmodule

