module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,
    rst_n,
    mul_a,
    mul_b,
    mul_en_in,
    mul_en_out,
    mul_out
);
    input clk;
    input rst_n;
    input mul_en_in;
    input [size-1:0] mul_a;
    input [size-1:0] mul_b;
    output reg mul_en_out;
    output reg [size*2-1:0] mul_out;

    reg [size-1:0] a_reg, b_reg;
    reg [size-1:0] a_pipe [0:1];
    reg [size-1:0] b_pipe [0:1];
    reg [size*2-1:0] mult_pipe [0:1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_reg <= 0;
            b_reg <= 0;
            a_pipe[0] <= 0;
            a_pipe[1] <= 0;
            b_pipe[0] <= 0;
            b_pipe[1] <= 0;
            mult_pipe[0] <= 0;
            mult_pipe[1] <= 0;
            mul_en_out <= 0;
            mul_out <= 0;
        end else begin
            if (mul_en_in) begin
                a_reg <= mul_a;
                b_reg <= mul_b;
            end
            // Shift registers for a and b
            a_pipe[1] <= a_pipe[0];
            a_pipe[0] <= a_reg;
            b_pipe[1] <= b_pipe[0];
            b_pipe[0] <= b_reg;

            // Compute partial product when data is valid
            if (mul_en_in) begin
                mult_pipe[0] <= a_reg * b_reg;
            end else begin
                mult_pipe[0] <= mult_pipe[0]; // hold previous value
            end

            // Shift the mult_pipe
            mult_pipe[1] <= mult_pipe[0];

            // Output valid when the multiplication result has propagated through the pipeline
            if (mul_en_in) begin
                mul_en_out <= 0;
            end else if (a_pipe[1] !== 0 || b_pipe[1] !== 0) begin
                mul_en_out <= 1;
                mul_out <= mult_pipe[1];
            end else begin
                mul_en_out <= 0;
            end
        end
    end
endmodule

module multi_pipe_8bit#(
    parameter size = 8
)(
    clk,      
    rst_n,       
    mul_a,       
    mul_b, 
    mul_en_in,

    mul_en_out,      
    mul_out    
);
    input clk;           
    input rst_n; 
    input mul_en_in;      
    input [size-1:0] mul_a;       
    input [size-1:0] mul_b;       

    output reg mul_en_out;  
    output reg [size*2-1:0] mul_out;    

    reg [size-1:0] a_reg;
    reg [size-1:0] b_reg;
    reg [4:0] cycle_count; // enough bits to count up to 8 cycles

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_reg <= 0;
            b_reg <= 0;
            mul_out <= 0;
            mul_en_out <= 0;
            cycle_count <= 0;
        end else begin
            if (mul_en_in) begin
                a_reg <= mul_a;
                b_reg <= mul_b;
                mul_out <= 0;
                mul_en_out <= 0;
                cycle_count <= 1;
            end else if (cycle_count != 0) begin
                // Perform partial product addition
                // Add (a_reg & {size{b_reg[0]}}) shifted appropriately
                // Accumulate partial products for each bit of b_reg
                integer i;
                reg [size*2-1:0] partial_sum;
                partial_sum = 0;
                for (i = 0; i < size; i = i + 1) begin
                    if (b_reg[i]) begin
                        partial_sum = partial_sum + (a_reg << i);
                    end
                end
                if (cycle_count == size) begin
                    // Final cycle
                    mul_out <= partial_sum;
                    mul_en_out <= 1;
                    cycle_count <= 0;
                end else begin
                    // Intermediate cycle
                    cycle_count <= cycle_count + 1;
                end
            end else begin
                // idle
                mul_en_out <= 0;
            end
        end
    end
endmodule

