module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    parameter ADD   = 6'b100000;
    parameter ADDU  = 6'b100001;
    parameter SUB   = 6'b100010;
    parameter SUBU  = 6'b100011;
    parameter AND   = 6'b100100;
    parameter OR    = 6'b100101;
    parameter XOR   = 6'b100110;
    parameter NOR   = 6'b100111;
    parameter SLT   = 6'b101010;
    parameter SLTU  = 6'b101011;
    parameter SLL   = 6'b000000;
    parameter SRL   = 6'b000010;
    parameter SRA   = 6'b000011;
    parameter SLLV  = 6'b000100;
    parameter SRLV  = 6'b000110;
    parameter SRAV  = 6'b000111;
    parameter LUI   = 6'b001111;

    reg [31:0] result;
    reg c_flag;
    reg n_flag;
    reg v_flag;
    reg z_flag;
    reg f_flag;

    wire [31:0] b_mux;
    wire [4:0] shamt;
    wire [31:0] shift_result;
    wire [31:0] add_sub_result;
    wire carry_out;
    wire overflow_flag;

    // For shift amount
    assign shamt = a[4:0];

    // B operand for shift instructions
    assign b_mux = (aluc == SLL || aluc == SLLV) ? {27'b0, shamt} : b;

    // Shift operations
    assign shift_result = (aluc == SLL || aluc == SLLV) ? (aluc == SLL ? a << shamt : a << a[4:0]) :
                          (aluc == SRL || aluc == SRLV) ? (aluc == SRL ? a >> shamt : a >> a[4:0]) :
                          (aluc == SRA || aluc == SRAV) ? (aluc == SRA ? (a >>> shamt) : (a >>> a[4:0])) : 32'b0;

    // Addition and subtraction
    wire [32:0] add_temp;
    assign add_temp = (aluc == ADD || aluc == ADDU || aluc == SLT || aluc == SLTU || aluc == SUB || aluc == SUBU) ? 
                      ( (aluc == SUB || aluc == SUBU || aluc == SLT || aluc == SLTU) ? {1'b0, a} - {1'b0, b} : {1'b0, a} + {1'b0, b} ) : 33'b0;

    assign add_sub_result = add_temp[31:0];
    assign carry_out = (aluc == ADD || aluc == ADDU || aluc == SLT || aluc == SLTU) ? add_temp[32] : 1'b0;

    // Overflow detection
    assign overflow_flag = ((aluc == ADD || aluc == SUB) && ((a[31] == b[31]) && (add_sub_result[31] != a[31]))) ? 1'b1 :
                           ((aluc == ADDU || aluc == SUBU || aluc == SLT || aluc == SLTU) ? 1'b0 : 1'b0);

    // Determine result based on aluc
    always @(*) begin
        case (aluc)
            ADD, ADDU: begin
                result = add_sub_result;
                c_flag = carry_out;
                v_flag = overflow_flag;
            end
            SUB, SUBU: begin
                result = add_sub_result;
                c_flag = ~carry_out;
                v_flag = overflow_flag;
            end
            AND: begin
                result = a & b;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            OR: begin
                result = a | b;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            XOR: begin
                result = a ^ b;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            NOR: begin
                result = ~(a | b);
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            SLT: begin
                result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            SLTU: begin
                result = (a < b) ? 32'd1 : 32'd0;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            SLL, SLLV, SRL, SRLV, SRA, SRAV: begin
                result = shift_result;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            LUI: begin
                result = {b[15:0], 16'b0};
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
            default: begin
                result = 32'b0;
                c_flag = 1'b0;
                v_flag = 1'b0;
            end
        endcase
    end

    // Zero flag
    always @(*) begin
        z_flag = (result == 32'b0) ? 1'b1 : 1'b0;
