    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] result;
    reg c; // carry
    reg v; // overflow
    reg n; // negative
    reg z; // zero
    reg f; // flag

    wire [31:0] b_inverted = ~b;
    wire [31:0] add_sub_result;
    wire [31:0] logic_result;
    wire [4:0] shamt = b[4:0];
    wire [31:0] shl_result, shr_result, sra_result;
    wire [31:0] sllv_result, srlv_result, srav_result;

    // Addition and subtraction
    wire [32:0] sum = (aluc == SUB || aluc == SUBU) ? {1'b0, a} + {1'b0, b_inverted} + (aluc == SUB || aluc == SUBU ? 1'b1 : 1'b0) : {1'b0, a} + {1'b0, b};
    assign add_sub_result = sum[31:0];
    assign c = sum[32];

    // Logic operations
    assign logic_result = (aluc == AND) ? (a & b) :
                          (aluc == OR) ? (a | b) :
                          (aluc == XOR) ? (a ^ b) :
                          (aluc == NOR) ? ~(a | b) :
                          (aluc == LUI) ? {b[15:0], 16'b0} :
                          32'b0;

    // Shift operations
    assign shl_result = a << shamt;
    assign shr_result = a >> shamt;
    assign sra_result = $signed(a) >>> shamt;

    // Variable shift operations
    assign sllv_result = a << b[4:0];
    assign srlv_result = a >> b[4:0];
    assign srav_result = $signed(a) >>> b[4:0];

    always @(*) begin
        case (aluc)
            ADD: begin
                result = add_sub_result;
                c = sum[32];
                v = (~a[31] & ~b[31] & result[31]) | (a[31] & b[31] & ~result[31]);
            end
            ADDU: begin
                result = add_sub_result;
                c = sum[32];
                v = 1'b0;
            end
            SUB: begin
                result = add_sub_result;
                c = ~sum[32];
                v = (~a[31] & b[31] & result[31]) | (a[31] & ~b[31] & ~result[31]);
            end
            SUBU: begin
                result = add_sub_result;
                c = ~sum[32];
                v = 1'b0;
            end
            AND: result = logic_result;
            OR: result = logic_result;
            XOR: result = logic_result;
            NOR: result = logic_result;
            LUI: result = logic_result;
            SLT: begin
                result = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
            end
            SLTU: begin
                result = (a < b) ? 32'b1 : 32'b0;
            end
            SLL: result = shl_result;
            SRL: result = shr_result;
            SRA: result = sra_result;
            SLLV: result = sllv_result;
            SRLV: result = srlv_result;
            SRAV: result = srav_result;
            default: result = 32'b0;
        end
    end

    // Assign outputs
    assign r = result;
    assign zero = (result == 0);
    assign negative = result[31];
    assign overflow = v;
    assign carry = c;
    assign flag = (aluc == SLT || aluc == SLTU);

endmodule

