    wire [31:0] sllv_result, srlv_result, srav_result;
    wire [31:0] logic_and, logic_or, logic_xor, logic_nor;
    wire [31:0] lui_result;
    wire [31:0] slt_result, sltu_result;

    // Assign shift amount
    assign shamt = {27'b0, a[4:0]};
    assign shamt_v = a[4:0];

    // For shift instructions, b is treated as shift amount
    assign b_in = (aluc == SLL || aluc == SRL || aluc == SRA) ? shamt : b;

    // For SLT/SLTU, prepare comparison values
    assign add_a = a;
    assign add_b = (aluc == ADDU || aluc == SLTU) ? b : 0;
    assign sub_b = b;

    // Shift operations
    assign sll_result = a << shamt_v;
    assign srl_result = a >> shamt_v;
    assign sra_result = ({32{a[31]}} << (32 - shamt_v)) | (a >> shamt_v);

    // Variable shift
    assign sllv_result = a << a[4:0];
    assign srlv_result = a >> a[4:0];
    assign srav_result = ({32{a[31]}} << (32 - a[4:0])) | (a >> a[4:0]);

