        carry = c_flag;
        // Overflow flag
        overflow = v_flag;
        // Flag (for example, zero flag)
        flag = zero;
    end

    assign r = result;
    assign zero = (result == 0);
    assign carry = c_flag;
    assign negative = result[31];
    assign overflow = v_flag;
    assign flag = zero;

