              s2_yellow = 2'd2,
              s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [31:0] counter;
    reg [31:0] duration;
    reg pass_req_d;

    // Clock divider for generating clock output (for example, 1Hz)
    // Adjust divisor as needed for desired clock display
    reg [7:0] clk_divider;
    assign clock = clk_divider;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_divider <= 0;
        end else begin
            clk_divider <= clk_divider + 1;
        end
    end

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= s1_red;
            counter <= 0;
            red <= 1;
            yellow <= 0;
            green <= 0;
            duration <= 100; // duration for red in clock cycles
            pass_req_d <= 0;
        end else begin
            pass_req_d <= pass_request;

            if (counter < duration) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                // Transition to next state
                if (state == s1_red) begin
                    if (pass_req_d) begin
                        // If pass request received, skip to green
                        state <= s3_green;
                        duration <= 100; // green duration
                        red <= 0;
                        yellow <= 0;
                        green <= 1;
                    end else begin
                        state <= s2_yellow;
                        duration <= 20; // yellow duration
                        red <= 0;
                        yellow <= 1;
                        green <= 0;
                    end
                end else if (state == s2_yellow) begin
                    state <= s3_green;
                    duration <= 100; // green duration
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end else if (state == s3_green) begin
                    state <= s1_red;
                    duration <= 100; // red duration
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
            end
        end
    end

endmodule

